from django.db import models
from ..models import TimeStampedModel
from ..platform_models import Tenant
class FabricSource(TimeStampedModel):tenant=models.ForeignKey(Tenant,on_delete=models.CASCADE);name=models.CharField(max_length=180);source_type=models.CharField(max_length=80);configuration=models.JSONField(default=dict);secret_reference=models.CharField(max_length=255,blank=True);enabled=models.BooleanField(default=False);sync_cursor=models.JSONField(default=dict)
class FabricEntity(TimeStampedModel):tenant=models.ForeignKey(Tenant,on_delete=models.CASCADE);entity_type=models.CharField(max_length=80,db_index=True);external_key=models.CharField(max_length=255);name=models.CharField(max_length=255);properties=models.JSONField(default=dict);classification=models.CharField(max_length=80,blank=True);source=models.ForeignKey(FabricSource,null=True,on_delete=models.SET_NULL)
class FabricRelationship(TimeStampedModel):tenant=models.ForeignKey(Tenant,on_delete=models.CASCADE);source=models.ForeignKey(FabricEntity,related_name='outgoing',on_delete=models.CASCADE);target=models.ForeignKey(FabricEntity,related_name='incoming',on_delete=models.CASCADE);relationship=models.CharField(max_length=100,db_index=True);properties=models.JSONField(default=dict);confidence=models.DecimalField(max_digits=5,decimal_places=4,null=True)
class FabricIndex(TimeStampedModel):tenant=models.ForeignKey(Tenant,on_delete=models.CASCADE);entity=models.OneToOneField(FabricEntity,on_delete=models.CASCADE);search_text=models.TextField();embedding_reference=models.CharField(max_length=255,blank=True);metadata=models.JSONField(default=dict)
